// Checks that every internal link the site renders (to card, archetype,
// family, deck and player pages) leads to a page that exists, i.e. one whose
// data was generated by build-data.mjs. Exits with code 1 when some don't, so
// the build fails instead of deploying broken links.
//
// Pages are rendered client-side from public/data/, so links are rebuilt from
// that data with the same slug functions the pages use, then checked the way
// each page resolves them (including its redirects). Card names without a
// page (banned cards, misspelt names) are shown as plain text, not linked.
//
// Avoids optional chaining and nullish coalescing: see build-data.mjs.

import { readFileSync, readdirSync } from 'fs'
import { resolve, join } from 'path'
import { fileURLToPath } from 'url'
import { nameToSlug, pilotToSlug } from '../src/utils/slugs.js'
import { cardPageSlug, makeCardPages } from '../src/utils/cardPages.js'

const __dirname = fileURLToPath(new URL('.', import.meta.url))
const dataDir = resolve(__dirname, '..', 'public', 'data')

// Broken links listed per page kind before "... and N more".
const MAX_REPORTED = +(process.env.MAX_REPORTED || 20)
// Pages linking to a broken link listed for it.
const MAX_SOURCES = 3

function read(path) {
  return JSON.parse(readFileSync(join(dataDir, path), 'utf-8'))
}

// Names (without .json) of the files in a data directory.
function names(dir) {
  return readdirSync(join(dataDir, dir)).filter(f => f.endsWith('.json')).map(f => f.slice(0, -5))
}

function eachFile(dir, fn) {
  for (const name of names(dir)) fn(read(join(dir, `${name}.json`)), name)
}

// --- Existing pages, resolved as each page does ---

const cardSlugs = new Set(names('card-details'))
// How pages pick the slug to link a card name to, if any.
const frontFaces = read('card-front-face-slugs.json')
const cardPages = makeCardPages(read('card-slugs.json'), frontFaces)
// CardPage redirects a front face's slug to the full card (fullCardSlug).
const frontFaceSlugs = new Set(Object.keys(frontFaces)
  .filter(name => cardSlugs.has(frontFaces[name]))
  .map(nameToSlug))
const archetypeSlugs = new Set(names('archetype-details'))
// ArchetypePage redirects aliases to their archetype.
const aliasMap = read('archetype-alias-map.json')
const families = read('families.json')
const familySlugs = new Set(families.map(f => f.slug))
const deckIds = new Set(names('deck-details'))
const playerSlugs = new Set(names('player-decks'))

const exists = {
  cards: slug => cardSlugs.has(slug) || frontFaceSlugs.has(slug),
  archetypes: slug => archetypeSlugs.has(slug) || archetypeSlugs.has(aliasMap[slug]),
  families: slug => familySlugs.has(slug),
  decks: id => deckIds.has(id),
  players: slug => playerSlugs.has(slug),
}

// --- Links rendered by the pages ---

// Broken links: path -> { count, sources }
const broken = new Map()
let checked = 0

function link(kind, slug, source) {
  checked++
  const ok = slug != null && slug !== '' && exists[kind](String(slug))
  if (ok) return
  const path = `/${kind}/${slug}`
  let entry = broken.get(path)
  if (!entry) broken.set(path, entry = { kind, count: 0, sources: [] })
  entry.count++
  if (entry.sources.length < MAX_SOURCES) entry.sources.push(source)
}

// Card names shown as plain text, having no page.
const unlinked = new Set()
function card(name, source) {
  const slug = cardPageSlug(cardPages, name)
  if (slug) link('cards', slug, source)
  else unlinked.add(name)
}
const archetype = (name, source) => link('archetypes', name ? nameToSlug(name) : name, source)

// Home (top decks, metagame), ArchetypesIndex, FamilyPage
for (const d of read('top_decks.json')) archetype(d.archetype_name, '/')
const metagame = read('metagame.json')
for (const e of metagame.meta_shares || metagame) archetype(e.archetype_name, '/')
for (const a of read('archetypes.json')) {
  archetype(a.name, '/archetypes')
  if (a.family) link('families', nameToSlug(a.family), '/archetypes')
}
for (const f of families) {
  for (const a of f.archetypes) archetype(a.name, `/families/${f.slug}`)
}

// CardsIndex, PauperPool
for (const c of read('cards.json')) link('cards', c.slug, '/cards')
for (const set of read('pauper_pool.json')) {
  for (const c of set.cards) link('cards', nameToSlug(c.name), '/sets')
}

// Watch, Creators, PlayersIndex
for (const v of read('videos.json')) archetype(v.archetype, '/watch')
for (const c of read('creators.json')) {
  if (c.player_slug) link('players', c.player_slug, '/creators')
  if (c.player_slug2) link('players', c.player_slug2, '/creators')
  for (const r of c.resources || []) {
    if (r.archetype_slug) link('archetypes', r.archetype_slug, `/players/${c.player_slug}`)
  }
}
for (const p of read('players.json')) link('players', p.slug, '/players')

// ArchetypePage: card galleries, family, community decklists
eachFile('archetype-details', (a, slug) => {
  const source = `/archetypes/${slug}`
  for (const c of (a.staples || []).concat(a.frequent || [])) card(c.name, source)
  if (a.family) link('families', nameToSlug(a.family), source)
})
eachFile('intel-decks', (decks, slug) => {
  const source = `/archetypes/${slug}`
  for (const d of decks) {
    link('decks', d.id, source)
    if (d.pilot) link('players', pilotToSlug(d.pilot), source)
  }
})

// CardPage, PlayerPage, DeckPage
eachFile('card-decks', (decks, slug) => {
  for (const d of decks) link('decks', d.id, `/cards/${slug}`)
})
eachFile('player-decks', (p, slug) => {
  const source = `/players/${slug}`
  for (const d of p.decks) {
    archetype(d.archetype, source)
    link('decks', d.id, source)
  }
})
eachFile('deck-details', (d, id) => {
  const source = `/decks/${id}`
  if (d.archetype) archetype(d.archetype, source)
  if (!d.decklist) return
  for (const c of (d.decklist.main || []).concat(d.decklist.side || [])) card(c.name, source)
})

// --- Report ---

if (broken.size === 0) {
  console.log(`Checked ${checked} internal links: none broken (${unlinked.size} card names have no page, so no link).`)
  process.exit(0)
}

const byKind = {}
for (const [path, entry] of broken) (byKind[entry.kind] = byKind[entry.kind] || []).push([path, entry])
console.error(`Checked ${checked} internal links: ${broken.size} lead to missing pages.`)
for (const kind of Object.keys(byKind)) {
  const entries = byKind[kind].sort((a, b) => b[1].count - a[1].count)
  console.error(`\n/${kind}/ (${entries.length}):`)
  for (const [path, { count, sources }] of entries.slice(0, MAX_REPORTED)) {
    const more = count > sources.length ? `, … (${count} links)` : ''
    console.error(`  ${path}  ← ${sources.join(', ')}${more}`)
  }
  if (entries.length > MAX_REPORTED) console.error(`  ... and ${entries.length - MAX_REPORTED} more`)
}
process.exit(1)
